  const stack = (arr, x) => { let y = 10; const tot = arr.reduce((a, b) => a + Math.max(1, b.v), 0); return arr.map(a => { const h = (Hh - 10 - arr.length * 6) * Math.max(1, a.v) / tot; const o = { ...a, x, y, h }; y += h + 6; return o; }); };
