  B.forEach((b, i) => { let yb = b.y; Cc.forEach((cc, j) => { const w = (i === j ? .45 : .55 * cc.v / Math.max(1, 100 - n2[i].v)); const h = b.h * w; if (h < 1.2) { yb += h; return; } const yc = cc.y + cc.h * (i / B.length), h2 = Math.max(1, cc.h / B.length); bands += `<path d="M${colX[1] + 20} ${yb} C${colX[2] - 90} ${yb} ${colX[2] - 90} ${yc} ${colX[2]} ${yc} L${colX[2]} ${yc + h2} C${colX[2] - 90} ${yc + h2} ${colX[2] - 90} ${yb + h} ${colX[1] + 20} ${yb + h} Z" fill="${pal[i % 7]}" opacity="${i === j ? .32 : .12}"/>`; yb += h; }); });
