  $('#rs', c).onclick = () => dToast('Lien sécurisé envoyé au client (lecture seule, valable 30 jours) · prototype');
  setTimeout(() => { if (mv0.alive) { playing = true; $('#tp', c).innerHTML = 'Pause'; } }, 600);
